/*
  холст.js — ВИД ОТ ГЕРОЯ. Мир на холсте 320×200, крупной точкой.

  Чем отличается от соседей: карта.js держит устройство мира — дороги,
  поиск пути, движение героя. Этот файл ничего про мир не решает, он
  только показывает: получает от карты, где герой и по какой дороге
  идёт, и рисует то, что он видит перед собой.

  МИРОВЫХ КООРДИНАТ ЗДЕСЬ НЕТ. Всё считается от экранной строки: где
  середина дороги, какой она ширины, что стоит по сторонам. Отказ от
  мировых координат — решение задания: настоящий поворот камеры с
  обходом вокруг дома запрещён разделом 12, а дешёвый поворот в такой
  рисовке делается переводом двух чисел.

  Шаг первый: небо, земля, дорога, горизонт. Больше ничего.
*/

'use strict';

window.ХОЛСТ = (function () {

const НАСТРОЙКИ = window.МИР_НАСТРОЙКИ;

let холст = null, кисть = null;

/* ═══ 1 · КРАСКИ ═══════════════════════════════════════════════════ */

const мешать = (а, б, доля) =>
  а.map((знач, и) => Math.round(знач + (б[и] - знач) * доля));

const цвет = (краска) => 'rgb(' + краска[0] + ',' + краска[1] + ',' + краска[2] + ')';

/* ═══ 2 · ПЕРСПЕКТИВА ══════════════════════════════════════════════
   Глубина: 0 у горизонта, 1 у нижнего края. Всё остальное — от неё. */

function глубина(строка) {
  const х = НАСТРОЙКИ.холст;
  const от = х.горизонт + х.отступГоризонта;
  return Math.max(0, Math.min(1, (строка - от) / (х.высота - от)));
}

const ширинаДороги = (строка) => {
  const х = НАСТРОЙКИ.холст;
  return х.дорогаУГоризонта + Math.pow(глубина(строка), х.законСужения) * х.дорогаРазмах;
};

/*  СЕРЕДИНА ДОРОГИ. Изгиб идёт от кривизны кольца, на котором стоит
    герой: чем кольцо теснее, тем сильнее ведёт. На луче и тропке
    изгиб равен нулю, и дорога идёт прямой.                        */
function серединаДороги(строка, изгиб) {
  const х = НАСТРОЙКИ.холст;
  const г = глубина(строка);
  return х.ширина / 2 +
    Math.sin(г * х.изгибЧастота + х.изгибСдвиг) * х.изгибРазмах * г * изгиб +
    Math.sin(г * х.изгибРябьЧастота) * х.изгибРябь * г * изгиб;
}

/* ═══ 3 · РИСОВАНИЕ ════════════════════════════════════════════════ */

function точки(x, y, ш, в, краска) {
  кисть.fillStyle = краска;
  кисть.fillRect(Math.round(x), Math.round(y), Math.max(1, Math.round(ш)),
                 Math.max(1, Math.round(в)));
}

function небо(п) {
  const х = НАСТРОЙКИ.холст;
  for (let y = 0; y < х.горизонт; y++) {
    const доля = Math.pow(y / х.горизонт, х.небоСтепень);
    точки(0, y, х.ширина, 1, цвет(мешать(п.небоВерх, п.небоНиз, доля)));
  }
  /* зарево у самого горизонта: небо у земли всегда светлее */
  for (let y = х.горизонт - х.заревоВысота; y < х.горизонт; y++) {
    кисть.globalAlpha = ((y - (х.горизонт - х.заревоВысота)) / х.заревоВысота) * х.заревоСила;
    точки(0, y, х.ширина, 1, цвет(п.зарево));
    кисть.globalAlpha = 1;
  }
}

function земля(п) {
  const х = НАСТРОЙКИ.холст;
  for (let y = х.горизонт; y < х.высота; y++) {
    точки(0, y, х.ширина, 1, цвет(мешать(п.землД, п.землБ, глубина(y))));
  }
}

/*  Дорога. Кромки протоптаны светлее, по середине две колеи темнее —
    это то, что отличает тракт от полосы краски.                   */
function дорога(п, изгиб) {
  const х = НАСТРОЙКИ.холст;
  for (let y = х.горизонт + х.отступГоризонта; y < х.высота; y++) {
    const ц = серединаДороги(y, изгиб), ш = ширинаДороги(y), г = глубина(y);
    const полотно = мешать(п.дорога, мешать(п.дорога, п.землБ, х.дорогаДаль), г);
    точки(ц - ш / 2, y, ш, 1, цвет(полотно));

    const кромка = цвет(мешать(п.дорога, п.землБ, х.кромкаСвет));
    точки(ц - ш / 2, y, ш * х.кромкаДоля, 1, кромка);
    точки(ц + ш / 2 - ш * х.кромкаДоля, y, ш * х.кромкаДоля, 1, кромка);

    кисть.globalAlpha = х.колеяПрозрачность;
    const колея = цвет(мешать(п.дорога, [0, 0, 0], х.колеяТень));
    точки(ц - ш * х.колеяСлева, y, ш * х.колеяДоля, 1, колея);
    точки(ц + ш * х.колеяСправа, y, ш * х.колеяДоля, 1, колея);
    кисть.globalAlpha = 1;
  }
}

/* ═══ 4 · ЧТО ВИДНО СНАРУЖИ ════════════════════════════════════════ */

function запуск(узел) {
  холст = узел;
  холст.width = НАСТРОЙКИ.холст.ширина;
  холст.height = НАСТРОЙКИ.холст.высота;
  кисть = холст.getContext('2d');
}

/*  `вид` приходит от карты: { изгиб }. Ничего больше этому файлу
    знать не нужно — он не решает, где герой, он показывает.      */
function рисовать(вид) {
  if (!кисть) return;
  const к = НАСТРОЙКИ.холст.краски;
  const п = Object.assign({}, к.ночь, к.зима);
  небо(п);
  земля(п);
  дорога(п, вид ? вид.изгиб : 0);
}

return { запуск: запуск, рисовать: рисовать, глубина: глубина,
         ширинаДороги: ширинаДороги, серединаДороги: серединаДороги };
})();
